tools.example:
add_block('simulink/Ports & Subsystems/Subsystem', [mdl '/Ctrl']);
add_block('simulink/Ports & Subsystems/Enable', [mdl '/Ctrl/Enable']);
set_param([mdl '/Ctrl/Enable'], 'StatesWhenEnabling', 'reset');

add_block('simulink/Ports & Subsystems/Subsystem', [mdl '/OnEdge']);
add_block('simulink/Ports & Subsystems/Trigger', [mdl '/OnEdge/Trigger']);
set_param([mdl '/OnEdge/Trigger'], 'TriggerType', 'rising');

add_block('simulink/Ports & Subsystems/Function-Call Generator', [mdl '/FCG']);
set_param([mdl '/FCG'], 'sample_time', '0.01', 'numberOfIterations', '2');
add_line(mdl, 'FCG/1', 'Task/Trigger', 'autorouting', 'on');

add_block('simulink/Ports & Subsystems/Function-Call Feedback Latch', [mdl '/Latch']);
add_line(mdl, 'TaskB/1', 'Latch/1', 'autorouting', 'on');
add_line(mdl, 'Latch/1', 'TaskA/2', 'autorouting', 'on');

add_block('simulink/Ports & Subsystems/For Each Subsystem', [mdl '/PerChannel']);
% configure partitioning in the For Each block dialog (Input Partition tab),
% e.g. slice a 4x1 input into four scalar channels, each with its own filter state

add_block('simulink/Ports & Subsystems/Enabled and Triggered Subsystem', [mdl '/ET']);
set_param([mdl '/ET/Trigger'], 'TriggerType', 'falling');
set_param([mdl '/ET/Enable'], 'StatesWhenEnabling', 'reset');

add_block('simulink/Ports & Subsystems/Switch Case', [mdl '/SC']);
set_param([mdl '/SC'], 'CaseConditions', '{1, [2 3]}', 'ShowDefaultCase', 'on');
add_block('simulink/Ports & Subsystems/Switch Case Action Subsystem', [mdl '/Case1']);
add_line(mdl, 'SC/1', 'Case1/Ifaction', 'autorouting', 'on');

add_block('simulink/Ports & Subsystems/Initialize Function', [mdl '/Init']);
% inside: Constant(10) -> State Writer with StateOwnerBlock = 'Discrete-Time Integrator'
set_param([mdl '/Init/State Writer'], 'StateOwnerBlock', [mdl '/Discrete-Time Integrator']);

add_block('simulink/Messages & Events/Send', [mdl '/Send']);
add_block('simulink/Ports & Subsystems/Message Triggered Subsystem', [mdl '/OnMsg']);
add_line(mdl, 'Send/1', 'OnMsg/Trigger', 'autorouting', 'on');

add_block('simulink/Signal Routing/Variant Sink', [mdl '/VSink']);
set_param([mdl '/VSink'], 'VariantControls', {'Mode==1','Mode==2'}, 'VariantActivationTime', 'code compile');
Mode = 1;

add_block('simulink/Signal Routing/Index Vector', [mdl '/Idx']);
add_line(mdl, 'Sel/1', 'Idx/1');   % control (index)
add_line(mdl, 'Table/1', 'Idx/2'); % data vector

mex timestwo.c
add_block('simulink/User-Defined Functions/S-Function', [mdl '/SF']);
set_param([mdl '/SF'], 'FunctionName', 'timestwo');

add_block('simulink/User-Defined Functions/S-Function Builder', [mdl '/SFB']);
% Outputs section:  y0[0] = 2.0 * u0[0];
% then click Build (generates <name>.c, <name>_wrapper.c and <name>.mex*)

% msfcn_times_two.m defines setup(block) and Output(block)
add_block('simulink/User-Defined Functions/Level-2 MATLAB S-Function', [mdl '/MS']);
set_param([mdl '/MS'], 'FunctionName', 'msfcn_times_two');

add_block('simulink/Logic and Bit Operations/Relational Operator', [mdl '/LE']);
set_param([mdl '/LE'], 'Operator', '<=');
add_block('simulink/Model Verification/Assertion', [mdl '/Assert']);
set_param([mdl '/Assert'], 'stopWhenAssertionFail', 'off', 'AssertionFailFcn', 'disp(''limit exceeded'')');
